    quiz: [
      { type: 'mcq', q: 'Which word is the adverb in “The very loud alarm startled us.”?', options: ['The', 'loud', 'startled', 'very'], answer: 3, why: '“Very” tells to what extent the alarm was loud, so it is a degree adverb modifying the adjective “loud”.', difficulty: 1 },
      { type: 'mcq', q: 'In “He drives surprisingly well,” which word does “surprisingly” modify?', options: ['The pronoun “He”', 'The verb “drives”', 'The adverb “well”', 'The whole sentence'], answer: 2, why: '“Surprisingly” says to what extent he drives well, so it modifies the adverb “well”.', difficulty: 2 },
      { type: 'mcq', q: 'Which sentence has the frequency adverb in its usual position?', options: ['I usually go to the gym.', 'I go usually to the gym.', 'I go to usually the gym.', 'Usually I to the gym go.'], answer: 0, why: 'Frequency adverbs normally go before the main verb. The other sentences break the natural word order.', difficulty: 2 },
      { type: 'multi', q: 'Which words are adverbs in “She worked quite carefully, and she finished early”?', options: ['quite', 'finished', 'carefully', 'early'], answers: [0, 2, 3], why: '“Quite” (degree), “carefully” (manner) and “early” (time) are adverbs. “Finished” is a verb.', difficulty: 2 },
      { type: 'truefalse', q: 'In “She worked hardly all night,” the word “hardly” correctly means “with great effort”.', answer: false, why: '“Hardly” means “barely”. To say she worked with effort, use the flat adverb “hard”: “She worked hard all night.”', difficulty: 2 },
      { type: 'fill', q: 'In “She never eats meat,” the word “never” tells how often, so it is an adverb of ____.', answer: 'frequency', accept: ['Frequency'], why: 'Always, usually, sometimes and never answer “how often?”, so they are adverbs of frequency.', difficulty: 1 },
      { type: 'match', q: 'Match each adverb type with an example.', pairs: [['Manner', 'carefully'], ['Place', 'outside'], ['Time', 'yesterday'], ['Degree', 'extremely']], why: 'Carefully tells how, outside tells where, yesterday tells when and extremely tells to what extent.', difficulty: 1 },
      { type: 'order', q: 'Arrange these words into a correct sentence with the frequency adverb in its usual position.', items: ['She', 'has', 'always', 'lived', 'here'], why: 'A frequency adverb goes after the first auxiliary (has) and before the main verb (lived).', difficulty: 2 },
    ],
    practice: [
      { type: 'mcq', q: 'In which sentence does an adverb modify an adjective?', options: ['She sang beautifully.', 'He is quite tall.', 'They arrived late.', 'I will read soon.'], answer: 1, why: '“Quite” modifies the adjective “tall”. In the other sentences the adverbs modify verbs.', difficulty: 2 },
      { type: 'mcq', q: 'In which sentence does an adverb modify another adverb?', options: ['She spoke softly.', 'I completely forgot.', 'He ran rather quickly.', 'The room is totally dark.'], answer: 2, why: '“Rather” modifies the adverb “quickly”. “Softly” and “completely” modify verbs, and “totally” modifies an adjective.', difficulty: 2 },
      { type: 'mcq', q: 'What type of adverb is “outside” in “Let’s play outside”?', options: ['Manner', 'Degree', 'Time', 'Place'], answer: 3, why: '“Outside” tells where the action takes place, so it is an adverb of place.', difficulty: 1 },
      { type: 'mcq', q: 'Which word correctly completes “The team played ____ in the final.”?', options: ['good', 'well', 'goodly', 'more good'], answer: 1, why: '“Played” is an action verb, so it needs an adverb. The adverb for good is well.', difficulty: 2 },
      { type: 'mcq', q: 'Which sentence places the manner adverb correctly?', options: ['She speaks fluently English.', 'She English speaks fluently.', 'She speaks English fluently.', 'Fluently speaks she English.'], answer: 2, why: 'A manner adverb normally follows the verb and its object; it should not sit between the verb and its object.', difficulty: 2 },
      { type: 'mcq', q: 'Which word completes “The exam was so difficult that we could ____ finish it.”?', options: ['hard', 'hardly', 'hardy', 'harder'], answer: 1, why: '“Hardly” means barely, which fits the meaning. “Hard” would mean with effort and does not fit here.', difficulty: 2 },
      { type: 'mcq', q: 'Which version most clearly says that rice was the only thing Ravi ate?', options: ['Only Ravi ate rice.', 'Ravi ate rice only when guests came.', 'Ravi ate only rice.', 'Ravi only ate rice yesterday.'], answer: 2, why: 'The focusing adverb “only” should sit directly before the word it limits: “only rice”. “Only Ravi” would limit the people instead.', difficulty: 3 },
      { type: 'multi', q: 'Which of these words can be used as adverbs without adding -ly?', options: ['well', 'hard', 'happily', 'fast'], answers: [0, 1, 3], why: 'Well, hard and fast keep the same form as adverbs. “Happily” already has -ly.', difficulty: 2 },
      { type: 'multi', q: 'Which sentences place the frequency adverb in its usual position?', options: ['I am always hungry after practice.', 'She has always lived here.', 'He eats never fish.', 'They go often to the cinema.'], answers: [0, 1], why: 'Frequency adverbs go after be (“am always”) and after the first auxiliary (“has always lived”). They do not follow a main verb as in “eats never”.', difficulty: 2 },
      { type: 'truefalse', q: 'In “Fortunately, the rain stopped before the match,” the word “fortunately” is an adverb that modifies the whole sentence.', answer: true, why: 'Some adverbs comment on a whole statement rather than one word. “Fortunately” shows the speaker’s attitude to the entire sentence.', difficulty: 2 },
      { type: 'fill', q: 'Meera plays chess ____ than I do. (well)', answer: 'better', accept: ['Better'], why: 'The adverb well is irregular: well, better, best.', difficulty: 2 },
      { type: 'order', q: 'Put these steps for working out what an adverb modifies in a sentence in a sensible order.', items: ['Find a word that answers how, when, where, how often or how much', 'Ask which word it describes', 'Name the word class of that described word', 'State the adverb type'], why: 'Spot the candidate adverb, find the word it describes, identify that word as verb, adjective or adverb, and then name the type.', difficulty: 2 },
    ],
